"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["62306"],{28123(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.escala_numerica_invalida","status":422,"titulo":"Escala do tipo de conceito num\xe9rico inv\xe1lida"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.escala_numerica_invalida","requisitos":[],"oQueAconteceu":["O tipo de conceito \xe9 de natureza `numerico`, e a escala enviada em `numerico` tem `escalaMinima` igual ou maior que `escalaMaxima`. A escala precisa ter uma faixa: o m\xednimo estritamente menor que o m\xe1ximo. A cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) e a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) conferem a mesma regra.","A recusa vem na lista `errors` da resposta, com `field` igual a `numerico`. Ela s\xf3 aparece quando a escala chegou completa; se falta alguma das tr\xeas partes, a recusa \xe9 [escala num\xe9rica obrigat\xf3ria](/erros/uniplus.configuracao.tipo_conceito.escala_numerica_obrigatoria). Se as casas decimais tamb\xe9m est\xe3o fora do limite, as duas recusas v\xeam na mesma resposta. Nada \xe9 gravado.","Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Corrija a escala para que `escalaMinima` seja menor que `escalaMaxima` e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);